mapper.insert:

	    SELECT
	        'WKHR'||
	        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(WORK_HIST_NO), LENGTH('WKHR' ) + 1)), 0) + 1, 6, '0')
	    FROM WORK_HISTORY

    INSERT INTO WORK_HISTORY (
        workHistNo
        , prjNo
        , userId
        , workDate
        , workTable
        , workType
        , workTarget
        , workContent
    ) VALUES (
        #{workHistNo}
        , #{prjNo}
        , #{userId}
        , #{workDate}
        , #{workTable}
        , #{workType}
        , #{workTarget}
        , #{workContent}
    )
